<aside class="sluyu-sidebar"><section class="sluyu-side-box"><h2>热门内容</h2><?php $popular = new WP_Query(['post_type' => 'post', 'posts_per_page' => 6, 'orderby' => 'comment_count']); if ($popular->have_posts()) : while ($popular->have_posts()) : $popular->the_post(); ?><a class="sluyu-side-post" href="<?php the_permalink(); ?>"><img src="<?php echo esc_url(wuai_sluyu_image(get_the_ID(), 'thumbnail')); ?>" alt=""><span><?php the_title(); ?><small><?php echo esc_html(get_the_date('m月d日')); ?></small></span></a><?php endwhile; wp_reset_postdata(); else : ?><p class="sluyu-empty">暂无内容</p><?php endif; ?></section><section class="sluyu-side-box"><h2>站点导航</h2><div class="sluyu-side-links"><a href="<?php echo esc_url(home_url('/')); ?>">首页</a><a href="<?php echo esc_url(get_permalink(get_option('page_for_posts')) ?: home_url('/')); ?>">全部文章</a><a href="<?php echo esc_url(wp_login_url()); ?>">用户中心</a></div></section></aside>
